insert into public.kb_documents(source_type,title,body,metadata,published) values
('Faq','Quy trình mua bất động sản gồm những bước nào?','Thông thường khách hàng xác định nhu cầu, xem bất động sản, kiểm tra hồ sơ, thỏa thuận điều kiện, ký kết và thực hiện thanh toán theo thỏa thuận. Chuyên viên sẽ hướng dẫn từng bước; thông tin pháp lý cần được người có chuyên môn xác minh.','{"draft":"m06"}',false),
('Faq','Quy trình thuê nhà gồm những bước nào?','Khách hàng trao đổi nhu cầu, xem nhà, thống nhất giá và điều khoản, kiểm tra hiện trạng rồi ký hợp đồng thuê. Các khoản tiền và thời điểm bàn giao cần ghi rõ trong hợp đồng.','{"draft":"m06"}',false),
('Faq','Đặt cọc mua nhà như thế nào?','Mức cọc, thời hạn và điều kiện hoàn trả phụ thuộc thỏa thuận của các bên. Khách hàng nên kiểm tra chủ thể, hồ sơ và đọc kỹ văn bản trước khi ký; TERAVA không đưa ra cam kết pháp lý.','{"draft":"m06"}',false),
('Faq','Đặt cọc thuê nhà cần lưu ý gì?','Nên ghi rõ số tiền cọc, mục đích, thời hạn thuê, điều kiện hoàn trả, trách nhiệm sửa chữa và biên bản bàn giao. Hãy yêu cầu chuyên viên giải thích nội dung chưa rõ.','{"draft":"m06"}',false),
('Faq','Cần hồ sơ gì để vay mua nhà?','Ngân hàng thường yêu cầu hồ sơ nhân thân, chứng minh thu nhập, thông tin khoản vay và hồ sơ bất động sản. Danh mục cụ thể tùy ngân hàng và từng thời điểm.','{"draft":"m06"}',false),
('Faq','Có thể vay bao nhiêu phần trăm giá trị nhà?','Tỷ lệ cho vay phụ thuộc chính sách ngân hàng, khả năng trả nợ và kết quả thẩm định. Khách hàng cần nhận tư vấn trực tiếp từ ngân hàng, không nên coi mức tham khảo là cam kết.','{"draft":"m06"}',false),
('Faq','Lãi suất vay mua nhà được tính thế nào?','Lãi suất, thời gian ưu đãi và biên độ sau ưu đãi do ngân hàng quy định. Hãy yêu cầu bảng minh họa dòng tiền và kiểm tra điều kiện trả nợ trước hạn.','{"draft":"m06"}',false),
('Faq','Mua nhà có những khoản phí nào?','Có thể phát sinh thuế, lệ phí, phí công chứng, phí ngân hàng, phí quản lý hoặc phí dịch vụ tùy giao dịch. Số tiền chính xác cần được đơn vị có thẩm quyền xác nhận.','{"draft":"m06"}',false),
('Faq','Thuê nhà có những khoản phí nào?','Ngoài tiền thuê và tiền cọc, có thể có phí quản lý, điện, nước, internet, gửi xe và dịch vụ khác. Cần hỏi rõ khoản nào đã bao gồm trong giá thuê.','{"draft":"m06"}',false),
('Faq','Làm sao đăng ký xem nhà?','Khách hàng chọn bất động sản quan tâm và gửi yêu cầu tư vấn hoặc đề nghị thời gian xem. Thời gian chỉ được xác nhận sau khi chuyên viên liên hệ và thống nhất.','{"draft":"m06"}',false),
('Faq','Có thể xem nhiều nhà trong một buổi không?','Có thể đề nghị xem nhiều bất động sản gần nhau, tùy tình trạng thực tế và lịch của các bên. Chuyên viên sẽ trao đổi để sắp xếp lộ trình phù hợp.','{"draft":"m06"}',false),
('Faq','Cần mang gì khi đi xem nhà?','Nên mang giấy tờ tùy thân khi cần làm thủ tục ra vào và chuẩn bị danh sách tiêu chí cần kiểm tra. Không chuyển tiền chỉ dựa trên thông tin tại buổi xem.','{"draft":"m06"}',false),
('Faq','Thủ tục sang tên nhà đất gồm những gì?','Thông thường các bên kiểm tra hồ sơ, ký văn bản phù hợp, thực hiện nghĩa vụ tài chính và đăng ký biến động. Trình tự cụ thể cần được cơ quan có thẩm quyền hoặc chuyên gia pháp lý xác nhận.','{"draft":"m06"}',false),
('Faq','Sang tên mất bao lâu?','Thời gian xử lý phụ thuộc loại hồ sơ, địa phương và tình trạng bổ sung giấy tờ. Chuyên viên không thể cam kết thời hạn thay cho cơ quan có thẩm quyền.','{"draft":"m06"}',false),
('Faq','Làm sao kiểm tra tình trạng pháp lý?','Khách hàng nên đối chiếu giấy tờ gốc, thông tin quy hoạch, hạn chế giao dịch và chủ thể sở hữu qua nguồn có thẩm quyền. TERAVA chỉ cung cấp thông tin đã được phép công bố.','{"draft":"m06"}',false),
('Faq','Sổ hồng riêng có ý nghĩa gì?','Đây là cách gọi phổ biến cho giấy chứng nhận cấp cho một bất động sản hoặc chủ thể cụ thể. Giá trị và phạm vi quyền phải được đọc trên giấy tờ và xác minh cho từng trường hợp.','{"draft":"m06"}',false),
('Faq','Nhà đang thế chấp có giao dịch được không?','Giao dịch có thể cần sự tham gia hoặc chấp thuận của bên nhận thế chấp và tuân thủ thủ tục liên quan. Khách hàng nên nhận tư vấn pháp lý độc lập trước khi quyết định.','{"draft":"m06"}',false),
('Faq','Giá đăng tin có thương lượng được không?','Khả năng thương lượng phụ thuộc chủ sở hữu và tình trạng giao dịch. Trợ lý không xác nhận giảm giá; chuyên viên sẽ ghi nhận đề nghị và phản hồi sau khi kiểm tra.','{"draft":"m06"}',false),
('Faq','Giá bất động sản được cập nhật khi nào?','Giá hiển thị lấy từ dữ liệu công bố hiện tại và có kèm thời điểm cập nhật. Khách hàng nên yêu cầu kiểm tra lại trước khi đặt cọc hoặc ký kết.','{"draft":"m06"}',false),
('Faq','Trạng thái Đã giữ chỗ nghĩa là gì?','Đã giữ chỗ cho biết bất động sản hiện không nên được giới thiệu như đang sẵn sàng. Trạng thái này không tự nó chứng minh một giao dịch đã hoàn tất.','{"draft":"m06"}',false),
('Faq','Trạng thái Đã bán nghĩa là gì?','Đã bán cho biết bất động sản không còn được giới thiệu là khả dụng. Thông tin này là trạng thái quản lý, không thay thế chứng từ giao dịch.','{"draft":"m06"}',false),
('Faq','Tôi có thể yêu cầu chuyên viên gọi lại không?','Khách hàng đăng nhập có thể đề nghị bàn giao cho chuyên viên. Cuộc gọi chỉ được thực hiện khi có số điện thoại đã xác minh và các điều kiện đồng ý liên hệ phù hợp.','{"draft":"m06"}',false),
('Faq','Có thể đề nghị lịch hẹn qua trợ lý không?','Khách hàng đăng nhập có thể đề nghị một khung giờ. Đây chỉ là thời gian đề xuất; chuyên viên cần liên hệ và xác nhận trước khi lịch hẹn có hiệu lực.','{"draft":"m06"}',false),
('Faq','Thông tin trò chuyện có được lưu không?','Lịch sử chỉ được lưu khi khách hàng chủ động chọn lưu hội thoại. Nếu không chọn, hệ thống chỉ duy trì dữ liệu tối thiểu cần thiết cho phiên.','{"draft":"m06"}',false),
('Faq','Trợ lý có thể tư vấn pháp lý không?','Trợ lý chỉ cung cấp thông tin chung từ nguồn được phép và không đưa ra ý kiến hay cam kết pháp lý cho trường hợp cụ thể. Hãy tham khảo cơ quan có thẩm quyền hoặc chuyên gia pháp lý.','{"draft":"m06"}',false);
